int set_ext_task_registers(struct task_struct *child, void __user *uregs)
{
    int ret;

    /* Flush and release coprocessors if applicable */
    flush_and_release_coprocessors();

    /* Copy extended register values from user space to task's thread information */
    ret = copy_from_user(&child->thread.ext_regs, uregs, sizeof(child->thread.ext_regs));
